use semver::Version;
use serde::Deserialize;
use std::collections::BTreeMap;
use std::fmt::Write;
use std::sync::OnceLock;

/// The reduced icon and the version's outlines, generated by `docs/brand/generate.py`.
const DATA: &str = include_str!("badge.json");

const HEIGHT: f64 = 20.0;
const CAP: f64 = 7.6;
const ICON: f64 = 13.0;
const PAD: f64 = 6.0;
const TRACKING: f64 = 6.0;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct BadgeData {
    accent: String,
    cap_height: f64,
    characters: BTreeMap<char, Character>,
    field: String,
    icon: String,
    ink: String,
}

#[derive(Deserialize)]
struct Character {
    advance: f64,
    path: String,
}

fn data() -> &'static BadgeData {
    static DATA_CELL: OnceLock<BadgeData> = OnceLock::new();
    DATA_CELL.get_or_init(|| serde_json::from_str(DATA).expect("badge data is valid"))
}

/// Render the version badge: the reduced icon on the ink field, the version on the accent, in the
/// style of the "Released with Presswerk" badge.
pub fn render(version: &Version) -> String {
    let data = data();
    let text = format!("v{version}");
    let scale = CAP / data.cap_height;
    let split = PAD + ICON + PAD;
    let top = (HEIGHT - CAP) / 2.0;

    let mut glyphs = String::new();
    let mut x = 0.0;
    for (index, ch) in text.chars().enumerate() {
        let character = &data.characters[&ch];
        if index > 0 {
            x += TRACKING;
        }
        write!(
            glyphs,
            r#"<path d="{}" fill="{}" transform="translate({:.2},{:.2}) scale({:.4})"/>"#,
            character.path,
            data.ink,
            split + PAD + x * scale,
            top,
            scale
        )
        .expect("writing to a string succeeds");
        x += character.advance;
    }

    let width = split + PAD + x * scale + PAD;
    let title = format!("Version {version}, released with Presswerk");
    format!(
        concat!(
            r#"<svg xmlns="http://www.w3.org/2000/svg" width="{width:.2}" height="{height:.2}" "#,
            r#"viewBox="0 0 {width:.2} {height:.2}" role="img" aria-label="{title}">"#,
            r#"<title>{title}</title>"#,
            r#"<rect width="{split:.2}" height="{height}" fill="{field}"/>"#,
            r#"<rect x="{split:.2}" width="{accent_width:.2}" height="{height}" fill="{accent}"/>"#,
            r#"<path d="{icon}" fill="{ink}" fill-rule="evenodd" "#,
            r#"transform="translate({pad:.2},{icon_top:.2}) scale({icon_scale:.4})"/>"#,
            "{glyphs}</svg>\n"
        ),
        width = width,
        height = HEIGHT,
        title = title,
        split = split,
        field = data.field,
        accent_width = width - split,
        accent = data.accent,
        icon = data.icon,
        ink = data.ink,
        pad = PAD,
        icon_top = (HEIGHT - ICON) / 2.0,
        icon_scale = ICON / 100.0,
        glyphs = glyphs,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_covers_every_version_character() {
        let characters = &data().characters;
        for ch in "v0123456789.-+".chars().chain('A'..='Z').chain('a'..='z') {
            assert!(characters.contains_key(&ch), "missing {ch:?}");
        }
    }

    #[test]
    fn badge_names_the_version() {
        let badge = render(&Version::parse("1.2.3-rc.1+build.5").unwrap());

        assert!(badge.starts_with(r#"<svg xmlns="http://www.w3.org/2000/svg" width=""#));
        assert!(
            badge.contains("<title>Version 1.2.3-rc.1+build.5, released with Presswerk</title>")
        );
        assert_eq!(
            badge.matches(r##"fill="#ECECEA" transform"##).count(),
            "v1.2.3-rc.1+build.5".len()
        );
        assert!(badge.ends_with("</svg>\n"));
    }

    #[test]
    fn longer_versions_make_wider_badges() {
        let width = |version: &str| {
            let badge = render(&Version::parse(version).unwrap());
            let start = badge.find(r#"width=""#).unwrap() + 7;
            let end = start + badge[start..].find('"').unwrap();
            badge[start..end].parse::<f64>().unwrap()
        };

        assert!(width("10.20.30") > width("1.2.3"));
    }
}
